```sql
-- 1. Ciclos distintos
SELECT DISTINCT ciclo FROM asignaturas;

-- 2. Asignaturas con más de 6 créditos
SELECT * FROM asignaturas WHERE creditos > 6;

-- 3. Alumnos activos cuyo nombre empieza por 'J'
SELECT * FROM alumnos
WHERE activo = TRUE AND nombre LIKE 'J%';

-- 4. Notas entre 5 y 8 (inclusive)
SELECT * FROM notas
WHERE nota >= 5 AND nota <= 8;
-- o equivalentemente:
SELECT * FROM notas
WHERE nota BETWEEN 5 AND 8;
```

```sql
-- 1. Alumnos sin email
SELECT * FROM alumnos WHERE email IS NULL;

-- 2. Notas entre 9 y 10
SELECT * FROM notas WHERE nota BETWEEN 9 AND 10;

-- 3. Asignaturas DAM o DAW
SELECT * FROM asignaturas WHERE ciclo IN ('DAM', 'DAW');

-- 4. Apellidos que empiezan por 'G'
SELECT * FROM alumnos WHERE apellido LIKE 'G%';

-- 5. Nombres de exactamente 4 caracteres
SELECT * FROM alumnos WHERE nombre LIKE '____';
-- Cada _ representa un carácter exacto
```
